import {gradeLabel} from './gradebook-model.mjs';
/* Adapted from EDUCADE public/teacher.js and public/teacher-data.js at
   1a49552d1d76d4d3d9f973369454331b0fe7ba7c, with the owner's permission.
   Reuses its class comparison, learning tabs, accuracy summaries, progress bars
   and radar geometry. Demo records are supplied separately and explicitly labelled. Percentage estimates do not write teacher achievement judgments. */
import {escape} from './workspace-shared.js';
import {learnerEvidence} from './assessment-model.mjs';
import {estimatedProgressBands,estimateProgressLevel} from './assessment-progress-scale.mjs';
export const learningTabs={overall:{name:'Overall'},foundations:{name:'Reading Foundations',domain:'reading',section:'foundations'},literacy:{name:'Literacy',domain:'reading',section:'comprehension'},writing:{name:'Writing',domain:'writing'},grammar:{name:'Grammar',domain:'grammar'},vocabulary:{name:'Vocabulary',domain:'vocabulary'}};
export function summarizePractice(evidence){
 const attempts=evidence.length,correct=evidence.filter(record=>record.correct===true).length;
 return {attempts,correct,score:attempts?Math.round(correct/attempts*100):null,independent:evidence.filter(r=>!r.supported).length,supported:evidence.filter(r=>r.supported).length,hints:evidence.filter(r=>r.hint).length};
}
export function classAxes(catalogue,scope){
 if(scope==='overall')return Object.entries(catalogue.domains).map(([domain,info])=>({id:domain,domain,label:info.name}));
 const tab=learningTabs[scope];
 if(scope==='foundations')return catalogue.groups.filter(g=>g.section==='foundations').flatMap(g=>g.skills.map(s=>({id:s.id,label:s.name})));
 return catalogue.profileAxes[tab.domain];
}
function axisRecords(catalogue,records,axis){
 if(axis.domain){const ids=new Set(catalogue.groups.filter(g=>g.domain===axis.domain&&(!axis.section||g.section===axis.section)).flatMap(g=>g.skills.map(s=>s.id)));return records.filter(r=>ids.has(r.skillId));}
 return records.filter(r=>r.skillId===axis.id);
}
export function axisStats(catalogue,records,axis){return summarizePractice(axisRecords(catalogue,records,axis));}
// EDUCADE's compactDomain / subjectEvidence pattern: expand within the table;
// keep profile navigation on the learner name and score buttons.
function compactClassEvidence(catalogue,records,student,axis,expandedDetails){
 const stats=summarizePractice(records);
 if(!stats.attempts)return '<p class="educade-no-evidence">No evidence yet for this area.</p>';
 const groups=catalogue.groups.map(group=>({...group,skills:group.skills.filter(skill=>records.some(r=>r.skillId===skill.id))})).filter(group=>group.skills.length);
 const key=kind=>'class-evidence-'+encodeURIComponent(student.id)+'-'+encodeURIComponent(axis.id==='all'&&kind!=='subject'?kind:axis.id)+'-'+encodeURIComponent(kind);
 const counts=`<p><strong>${stats.correct}/${stats.attempts}</strong> correct · ${stats.hints} hints</p><p>${stats.independent} independent · ${stats.supported} supported</p>`;
 const skills=groups.flatMap(group=>group.skills);
 const history=skill=>{
  const attempts=records.filter(r=>r.skillId===skill.id).slice().sort((a,b)=>(b.week||0)-(a.week||0)||(b.day||0)-(a.day||0)),summary=summarizePractice(attempts),detailKey=key(skill.id);
  return `<details class="educade-inline-skill" data-class-detail="${detailKey}" ${expandedDetails?.has(detailKey)?'open':''}><summary><strong>${escape(skill.name)}</strong><span>${summary.correct}/${summary.attempts} correct · ${summary.hints} hints</span></summary><p>${summary.independent} independent · ${summary.supported} supported</p><div class="educade-inline-history" role="region" aria-label="${escape(student.name)} · ${escape(skill.name)} responses" tabindex="0">${attempts.map((record,index)=>`<article><h5>${record.week?'Week '+escape(record.week)+(record.day?' · Day '+escape(record.day):''):'Response '+(attempts.length-index)}</h5><p class="educade-response-meta">${record.correct?'Correct':'Try again'} · ${record.supported?'Supported':'Independent'} · ${record.hint?'Hint used':'No hint used'}</p><p>${record.response?escape(record.response):'Response text not available.'}</p></article>`).join('')}</div></details>`;
 };
 const details=groups.map(group=>`<section class="educade-inline-group"><h4>${escape(group.name)}</h4>${group.skills.map(history).join('')}</section>`).join('');
 return counts+(axis.domain?`<h4>Skills encountered</h4><ul>${skills.map(skill=>`<li>${escape(skill.name)}</li>`).join('')}</ul><details class="educade-inline-subject" data-class-detail="${key('subject')}" ${expandedDetails?.has(key('subject'))?'open':''}><summary>Explore ${escape(axis.label.toLowerCase())} skills</summary>${details}</details>`:details);
}

export function estimatedProgressHTML(score,label){
 const level=estimateProgressLevel(score);
 if(!level)return '<span class="educade-no-evidence">No evidence yet</span>';
 return `<span class="educade-estimated-level" data-level="${level.code}" role="img" aria-label="${escape(label)}: estimated ${level.code}, ${level.label}, from ${level.percentage} percent practice accuracy"><strong>${level.code}</strong><span>${level.label}<small>${level.percentage}% · Estimated</small></span></span>`;
}
export const estimatedScaleKeyHTML=()=>`<div class="educade-scale-key" role="group" aria-label="Estimated B to M plus percentage bands">${estimatedProgressBands.map(level=>`<span><strong>${level.code}</strong> ${level.min}–${level.max}%</span>`).join('')}</div>`;
export const progressBar=(score,label)=>score===null?'<span class="educade-no-evidence">No evidence yet</span>':`<span class="educade-hp" role="img" aria-label="${escape(label)}: ${score} percent"><svg class="educade-hp-track" viewBox="0 0 100 12" preserveAspectRatio="none" aria-hidden="true"><rect class="educade-hp-background" width="100" height="12" rx="6"/><rect class="educade-hp-fill ${score<70?'needs-practice':''}" width="${score}" height="12" rx="6"/></svg><strong>${score}%</strong></span>`;
const avatar=(student,portrait)=>`<span class="educade-avatar" aria-hidden="true">${escape(student.initials || student.name.slice(0,1))}${portrait==='photos'&&!student.demo?`<img src="/api/profiles/learners/${encodeURIComponent(student.id)}/image" alt="" loading="lazy">`:''}</span>`;
export function classOverviewHTML(data){
 const {students,lessons,scope,mode,search,sort,portrait,catalogue}=data;
 const withEvidence=students.filter(s=>learnerEvidence(lessons,s.id).length || data.records?.some(r=>r.learnerId===s.id) || data.activities?.some(a=>a.entries?.some(r=>r.learnerId===s.id&&(r.published||r.draft)))).length;
 return `<div class="educade-summary"><div><span class="educade-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M15 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/></svg></span><strong>${students.length}</strong><span>students</span></div><div><span class="educade-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 20h16M6 16V9m6 7V4m6 12v-5"/></svg></span><strong>${withEvidence}</strong><span>with evidence</span></div><div><span class="educade-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg></span><strong>${students.length-withEvidence}</strong><span>awaiting evidence</span></div></div><section class="assessment-card educade-class-comparison"><div class="educade-class-toolbar"><label>Find a learner<input type="search" data-class-search placeholder="Search students" value="${escape(search)}"></label><label>Sort learners<select data-class-sort><option value="name" ${sort==='name'?'selected':''}>Name A–Z</option><option value="evidence" ${sort==='evidence'?'selected':''}>Least lesson evidence first</option></select></label><label>Portrait style<select data-class-portrait><option value="photos" ${portrait==='photos'?'selected':''}>Photos / avatars</option><option value="initials" ${portrait==='initials'?'selected':''}>Initials</option></select></label></div><div class="educade-learning-tabs" role="tablist" aria-label="Class learning domains">${Object.entries(learningTabs).map(([id,tab])=>`<button type="button" role="tab" data-class-scope="${id}" aria-selected="${scope===id}" tabindex="${scope===id?'0':'-1'}">${tab.name}</button>`).join('')}</div><div class="educade-data-view"><p>Recorded skill practice${mode==='standards'?' · Estimated B–M+':''}</p><div class="educade-mode-switch" role="group" aria-label="Class data view">${[['bars','Progress bars'],['heatmap','Class heatmap'],['standards','Practice estimate']].map(([id,label])=>`<button type="button" data-class-mode="${id}" aria-pressed="${mode===id}">${label}</button>`).join('')}</div></div>${mode==='standards'?estimatedScaleKeyHTML():''}<div class="educade-table-scroll" role="region" aria-label="${escape(learningTabs[scope].name)} class comparison" tabindex="0"><table class="educade-class-table"><caption class="sr-only">Learners and recorded ${escape(learningTabs[scope].name)} evidence</caption><thead><tr><th scope="col">Student</th>${(data.source==='teacher'?[]:classAxes(catalogue,scope)).map(axis=>`<th scope="col"><button type="button" data-class-axis="${escape(axis.id)}" aria-expanded="${data.expandedAxis===axis.id}"><strong>${escape(axis.label)}</strong><span>${data.expandedAxis===axis.id?'− Hide evidence':'+ Show evidence'}</span></button></th>`).join('')}${data.source&&data.source!=='automatic'?'<th scope="col">Teacher assessments</th>':''}</tr></thead><tbody data-class-rows>${classRowsHTML(data)}</tbody></table></div><p class="educade-comparison-note">${mode==='standards'?'B–M+ levels are provisional estimates from practice accuracy.':'Bars and heatmap show accuracy only for responses linked to a skill.'} Unmapped quizzes and lesson feedback remain available in each learner’s evidence.</p></section>`;
}
function teacherResultsHTML(data,student){
 const rows=(data.activities||[]).flatMap(a=>(a.entries||[]).filter(r=>r.learnerId===student.id).map(r=>({a,...r}))).filter(r=>r.published||r.draft).sort((a,b)=>(b.published?.at||b.draft?.at||0)-(a.published?.at||a.draft?.at||0));
 const latest=rows.find(r=>r.published),drafts=rows.filter(r=>r.draft&&r.draft.at!==r.published?.at).length;
 return `${latest?`<span class="evidence-teacher-grade"><strong>${escape(gradeLabel(latest.published,latest.published.activity))}</strong><small>${escape(latest.published.activity.title)} · Published</small></span>`:'<span class="educade-no-evidence">No published teacher grade</span>'}${drafts?`<small>${drafts} private draft${drafts===1?'':'s'}</small>`:''}<button type="button" class="text-button" data-assessment-learner="${escape(student.id)}">View assessments</button>`;
}
function wideEvidenceHTML(data,student,axes,studentRecords,axis){
 const relevant=axis?axisRecords(data.catalogue,studentRecords,axis):data.scope==='overall'?studentRecords:studentRecords.filter(r=>axes.some(a=>axisRecords(data.catalogue,[r],a).length)),stats=summarizePractice(relevant),latest=[...relevant].sort((a,b)=>(b.week||0)-(a.week||0)||(b.day||0)-(a.day||0))[0];
 const title=axis?.label||'Learning evidence',code=latest?data.catalogue.mappings[latest.skillId]?.code:'',target=axis?.id||'';
 return `<section class="evidence-wide" data-wide-evidence="${escape(target)}" role="region" aria-label="${escape(student.name)} · ${escape(title)} evidence"><svg class="evidence-outline" aria-hidden="true"><path/></svg><div class="evidence-wide-heading"><div><h3>${escape(title)} · ${escape(student.name)}</h3><p>${axis?'Recorded skill practice':'Evidence across the selected learning area'}</p></div><button type="button" class="evidence-close" aria-label="Close ${escape(title)} evidence" ${axis?`data-class-axis="${escape(axis.id)}"`:`data-expand-learner="${escape(student.id)}"`}>×</button></div><div class="evidence-metrics"><span><strong>${stats.correct}/${stats.attempts}</strong> correct · ${stats.hints} hints</span><span>${stats.score===null?'No evidence yet':stats.score+'% accuracy'}</span><span>${stats.independent} independent · ${stats.supported} supported</span></div><div class="evidence-wide-grid"><article><h4>Latest response</h4>${latest?`<p class="evidence-sample-response">${escape(latest.response||'No response text saved.')}</p><p class="educade-response-meta">${latest.correct?'Correct':'Try again'} · ${latest.supported?'Supported':'Independent'} · ${latest.hint?'Hint used':'No hint used'}</p>${latest.week?`<small>Week ${latest.week} · Day ${latest.day||'—'}</small>`:''}`:'<p>No evidence yet for this area.</p>'}</article><article class="evidence-history"><h4>Skills &amp; response history</h4>${compactClassEvidence(data.catalogue,relevant,student,axis||{id:'all',label:'learning',domain:'all'},data.expandedDetails)}</article><article><h4>Teacher review</h4>${teacherResultsHTML(data,student)}<p class="std-note">Record a judgment, feedback and the next learning step.</p><button type="button" class="teacher-button secondary" data-assess-skill="${escape(latest?.skillId||axis?.id||'')}" data-assess-learner="${escape(student.id)}" data-assess-code="${escape(code)}">Record assessment</button></article></div></section>`;
}
export function classRowsHTML(data){
 const {students,lessons,catalogue,scope,mode,search,sort,portrait,records=[]}=data,axes=data.source==='teacher'?[]:classAxes(catalogue,scope),teacher=data.source&&data.source!=='automatic',columns=axes.length+(teacher?1:0);
 const filtered=students.filter(s=>s.name.toLocaleLowerCase().includes(search.toLocaleLowerCase())).slice().sort((a,b)=>(sort==='evidence'?learnerEvidence(lessons,a.id).length-learnerEvidence(lessons,b.id).length:0)||a.name.localeCompare(b.name));
 return filtered.map(student=>{
  const studentRecords=records.filter(r=>r.learnerId===student.id),axis=axes.find(a=>a.id===data.expandedAxis),open=data.expandedLearner===student.id,expanded=columns>0&&(open||axis),detailId='wide-evidence-'+encodeURIComponent(student.id);
  return `<tr class="${expanded?'educade-expanded-learner':''}" data-evidence-student="${escape(student.id)}"><th scope="row" ${expanded?'rowspan="2"':''}><div class="educade-learner">${avatar(student,portrait)}<div><button type="button" data-assessment-learner="${escape(student.id)}" class="educade-profile-link">${escape(student.name)}</button>${axes.length?`<button type="button" data-expand-learner="${escape(student.id)}" class="educade-evidence-link" aria-expanded="${open}" aria-controls="${detailId}" aria-label="${open?'Hide':'Show'} learning evidence for ${escape(student.name)}">${open?'− Hide':'+ Show'} learning evidence</button>`:''}<small>${student.demo?studentRecords.length+' sample responses':learnerEvidence(lessons,student.id).length+' lessons with evidence'}</small></div></div></th>${axes.map(a=>{const stats=axisStats(catalogue,studentRecords,a);return `<td data-score-axis="${escape(a.id)}" class="${axis?.id===a.id?'evidence-selected-cell':''}"><button type="button" class="educade-score-cell ${mode==='heatmap'?'educade-heat-cell':''}" data-class-evidence="${escape(a.id)}" data-class-learner="${escape(student.id)}">${mode==='standards'?estimatedProgressHTML(stats.score,a.label):mode==='heatmap'?`<span class="educade-heat ${stats.score===null?'empty':stats.score<70?'needs-practice':'has-evidence'}">${stats.score===null?'No evidence yet':stats.score+'%'}</span>`:progressBar(stats.score,a.label)}</button></td>`;}).join('')}${teacher?`<td class="evidence-teacher-cell">${teacherResultsHTML(data,student)}</td>`:''}</tr>${expanded?`<tr class="evidence-detail-row"><td colspan="${columns}" id="${detailId}">${wideEvidenceHTML(data,student,axes,studentRecords,axis)}</td></tr>`:''}`;
 }).join('')||`<tr><td colspan="${columns+1}"><p class="assessment-empty">${students.length?'No learners match your search.':'Add learners from Classes to begin.'}</p></td></tr>`;
}

export function practiceRadarHTML(axes,scores){
 // Preserve EDUCADE's missing-evidence rule: no missing point is plotted at zero,
 // and no polygon bridges a missing result.
 if(scores.filter(score=>score!==null).length<3)return '<p class="educade-no-evidence">A skill profile will appear after at least three areas have linked evidence.</p>';
 const count=axes.length,cx=250,cy=200,radius=125,point=(i,r)=>[cx+Math.sin(i*2*Math.PI/count)*r,cy-Math.cos(i*2*Math.PI/count)*r];
 const polygon=r=>axes.map((axis,i)=>point(i,r).join(',')).join(' ');
 const area=scores.every(score=>score!==null)?`<polygon class="educade-radar-area" points="${scores.map((score,i)=>point(i,radius*score/100).join(',')).join(' ')}"/>`:scores.map((score,i)=>{const next=(i+1)%count;if(score===null||scores[next]===null)return '';const a=point(i,radius*score/100),b=point(next,radius*scores[next]/100);return `<line class="educade-radar-area" x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}"/>`;}).join('');
 return `<svg class="educade-practice-radar" viewBox="0 0 500 400" role="img" aria-label="Recorded skill practice profile; missing evidence is omitted">${[.25,.5,.75,1].map(n=>`<polygon class="educade-radar-grid" points="${polygon(radius*n)}"/>`).join('')}${area}${axes.map((axis,i)=>{const end=point(i,radius),label=point(i,radius+34),dot=scores[i]===null?null:point(i,radius*scores[i]/100);return `<line class="educade-radar-axis" x1="${cx}" y1="${cy}" x2="${end[0]}" y2="${end[1]}"/><text x="${label[0]}" y="${label[1]}" text-anchor="middle">${escape(axis.label)}</text>${dot?`<circle cx="${dot[0]}" cy="${dot[1]}" r="4"/>`:''}`;}).join('')}</svg>`;
}
